<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Theme\Infrastructure\Driven;

use Psr\EventDispatcher\EventDispatcherInterface;
use Closure;
use Override;
use Throwable;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeWriteGateway;
use Civi\Lughauth\Features\Document\Theme\Infrastructure\Connector\Pdo\ThemePdoConnector;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeSlide;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeCursor;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeFilter;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\Theme\Domain\Theme;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class ThemeWriteRepositoryAdapter implements ThemeWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly ThemePdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(ThemeRef $ref): ?Theme
    {
        return $this->conn->retrieveForUpdate(new ThemeFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?ThemeFilter $filter = null, ?ThemeCursor $cursor = null): ThemeSlide
    {
        $this->logDebug("List for update of Theme on adapter ");
        $span = $this->startSpan("List for update of Theme on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new ThemeSlide(function (ThemeSlide $slide, ?ThemeCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new ThemeCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(ThemeFilter $filter): ?Theme
    {
        $this->logDebug("Retrieve for update of Theme on adapter ");
        $span = $this->startSpan("Retrieve for update of Theme on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(ThemeFilter $filter): bool
    {
        $this->logDebug("Exists for update of Theme on adapter ");
        $span = $this->startSpan("Exists for update of Theme on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?ThemeFilter $filter = null): int
    {
        $this->logDebug("Count for update of Theme on adapter ");
        $span = $this->startSpan("Count for update of Theme on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(Theme $entity, ?Closure $verify = null): Theme
    {
        $this->logDebug("Count for Theme on adapter ");
        $span = $this->startSpan("Count for Theme on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('theme', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(ThemeRef $ref, Theme $entity): Theme
    {
        $this->logDebug("Count for Theme on adapter ");
        $span = $this->startSpan("Count for Theme on adapter");
        try {
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('theme', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(Theme $entity): bool
    {
        $this->logDebug("Count for Theme on adapter ");
        $span = $this->startSpan("Count for Theme on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('theme', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(Theme $entity): void
    {
        $this->logDebug("Count for Theme on adapter ");
        $span = $this->startSpan("Count for Theme on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
